<?php
declare(strict_types=1);
namespace Vendor\ContaoIssueServiceBundle\Application;
use Symfony\Component\Uid\Uuid;
use Vendor\ContaoIssueServiceBundle\Domain\Dto\CreateIssueCommand;
use Vendor\ContaoIssueServiceBundle\Repository\IssueRepository;
use Vendor\ContaoIssueServiceBundle\Repository\ServiceRepository;
final class IssueApplicationService { public function __construct(private readonly IssueRepository $issues,private readonly ServiceRepository $services,private readonly TicketNumberGenerator $numbers,private readonly NotificationService $notifications){} public function create(CreateIssueCommand $c):array{if(!$this->services->categoryBelongsToService($c->categoryId,$c->serviceId))throw new \InvalidArgumentException('Category does not belong to service.');$db=$this->issues->connection();return $db->transactional(function()use($c,$db){$service=$db->fetchAssociative('SELECT alias FROM tl_issue_service WHERE id=:id AND published=1',['id'=>$c->serviceId]);if(false===$service)throw new \InvalidArgumentException('Unknown service.');$status=(int)$db->fetchOne('SELECT id FROM tl_issue_status WHERE is_initial=1 AND published=1 ORDER BY sort_order LIMIT 1');if(!$status)throw new \RuntimeException('Initial status is missing.');$uuid=Uuid::v7();$ticket=$this->numbers->next((string)$service['alias']);$now=(new \DateTimeImmutable())->format('Y-m-d H:i:s');$db->insert('tl_issue',['tstamp'=>time(),'uuid'=>$uuid->toBinary(),'ticket_number'=>$ticket,'member_id'=>$c->memberId,'guest_access_hash'=>$c->guestAccessHash,'service_id'=>$c->serviceId,'category_id'=>$c->categoryId,'status_id'=>$status,'issue_type'=>$c->type,'title'=>$c->title,'description'=>$c->description,'priority'=>'normal','created_at'=>$now,'updated_at'=>$now,'last_public_activity_at'=>$now,'version'=>1]);$id=(int)$db->lastInsertId();$db->insert('tl_issue_history',['issue_id'=>$id,'event_type'=>'issue_created','actor_type'=>$c->memberId?'member':'guest','actor_id'=>$c->memberId,'new_value'=>json_encode(['ticket'=>$ticket],JSON_THROW_ON_ERROR),'created_at'=>$now]);$this->notifications->enqueue($id,'issue_created');return ['id'=>$id,'uuid'=>$uuid->toRfc4122(),'ticketNumber'=>$ticket];});} }
